import time, numpy as np, mujoco
base=open('model_ref.xml').read()
def mkmodel(xml): return mujoco.MjModel.from_xml_string(xml)
def run(model, seed, total=2.0):
    d = mujoco.MjData(model)
    rng = np.random.default_rng(seed)
    d.qpos += rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(model,d)
    for _ in range(int(total/model.opt.timestep)): mujoco.mj_step(model,d)
    st = np.zeros(mujoco.mj_stateSize(model, mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(model,d,st,mujoco.mjtState.mjSTATE_FULLPHYSICS)
    return st
def mkopt(inner):
    return base.replace('<compiler autolimits="true"/>', '<compiler autolimits="true"/>\n  <option '+inner+'/>')
def timed(model, seeds=[7,13,21,34,55,89]):
    ts=[]
    for s in seeds:
        t0=time.perf_counter(); run(model,s); ts.append(time.perf_counter()-t0)
    return np.array(ts)
REF=mkmodel(base)
tr=timed(REF)
print('ref %.4f'%tr.mean())
cands={
 'pgs': 'solver="PGS"',
 'pgs_tol12': 'solver="PGS" tolerance="1e-12" iterations="1000"',
 'dense_pgs_tol12': 'solver="PGS" tolerance="1e-12" iterations="1000" jacobian="dense"',
 'pgs_tol14': 'solver="PGS" tolerance="1e-14" iterations="2000"',
 'pgs_dense_tol14': 'solver="PGS" tolerance="1e-14" iterations="2000" jacobian="dense"',
}
seeds=[3,17,42]
refs={s:run(REF,s) for s in seeds}
for name,inner in cands.items():
    m=mkmodel(mkopt(inner))
    t=timed(m); d=[np.abs(run(m,s)-refs[s]).max() for s in seeds]
    print('%-16s %6.2f%%  mean %.4f  maxdiff %.2e  (niter sample %d)'%(name,100*t.mean()/tr.mean(),t.mean(),max(d), m.opt.iterations))
